BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
SELECT jsonb_build_object('start','2026-10-26T09:00:00+08:00','end','2026-10-27T09:00:00+08:00','n',count(*),
 'min_time',min(event_time),'max_time',max(event_time),
 'missing_origin',count(*) FILTER(WHERE NOT(summary_json ? 'request_origin')),
 'truncated',count(*) FILTER(WHERE request_body_truncated),
 'linked',count(*) FILTER(WHERE usage_log_id IS NOT NULL),
 'completed',count(*) FILTER(WHERE completed_at IS NOT NULL),
 'failed_responses',count(*) FILTER(WHERE response_status<200 OR response_status>=300),
 'pending_recheck',count(*) FILTER(WHERE usage_link_version<>usage_link_checked_version),
 'precise',count(*) FILTER(WHERE usage_match_method='request_id'),
 'timing',count(*) FILTER(WHERE usage_match_method='timing'))
 FROM token_analysis_request_summaries WHERE event_time >= TIMESTAMPTZ '2026-10-26T09:00:00+08:00' AND event_time < TIMESTAMPTZ '2026-10-27T09:00:00+08:00';
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);

BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM (
 SELECT endpoint,coalesce(summary_json->'request_origin'->>'kind','missing') kind,
 coalesce(summary_json->'request_origin'->>'reason','missing') reason,
 count(*) n,count(*) FILTER(WHERE usage_log_id IS NULL) unlinked
 FROM token_analysis_request_summaries WHERE event_time >= TIMESTAMPTZ '2026-10-26T09:00:00+08:00' AND event_time < TIMESTAMPTZ '2026-10-27T09:00:00+08:00' GROUP BY 1,2,3 ORDER BY 1,2,3) x;
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);

BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
WITH s AS MATERIALIZED (SELECT * FROM token_analysis_request_summaries WHERE event_time >= TIMESTAMPTZ '2026-10-26T09:00:00+08:00' AND event_time < TIMESTAMPTZ '2026-10-27T09:00:00+08:00'),
 j AS (SELECT s.*,u.id bill_id,u.request_id bill_request_id,u.user_id bill_user_id,u.api_key_id bill_api_key_id,
 (u.request_id='client:'||s.client_request_id OR (s.response_id<>'' AND u.request_id=s.response_id)) exact_key
 FROM s LEFT JOIN usage_logs u ON u.id=s.usage_log_id
 AND u.created_at>=TIMESTAMPTZ '2026-10-26T09:00:00+08:00'-INTERVAL '2 hours' AND u.created_at<TIMESTAMPTZ '2026-10-27T09:00:00+08:00'+INTERVAL '2 hours')
 SELECT jsonb_build_object('attached',count(*) FILTER(WHERE usage_log_id IS NOT NULL),
 'joined',count(bill_id),'attached_outside_join_or_missing',count(*) FILTER(WHERE usage_log_id IS NOT NULL AND bill_id IS NULL),
 'exact_link_key_mismatch',count(*) FILTER(WHERE usage_match_method='request_id' AND bill_id IS NOT NULL AND NOT exact_key),
 'key_mismatch',count(*) FILTER(WHERE api_key_id IS NOT NULL AND bill_api_key_id<>api_key_id),
 'user_mismatch',count(*) FILTER(WHERE user_id IS NOT NULL AND bill_user_id<>user_id),
 'shared_bills', (SELECT count(*) FROM (SELECT usage_log_id FROM s WHERE usage_log_id IS NOT NULL GROUP BY 1 HAVING count(*)>1) d),
 'extra_shared_rows',(SELECT coalesce(sum(n-1),0) FROM (SELECT count(*) n FROM s WHERE usage_log_id IS NOT NULL GROUP BY usage_log_id HAVING count(*)>1) d)) FROM j;
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);

BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM (
 SELECT archive_id,event_time,summary_json->'request_origin' origin,usage_log_id,usage_match_method,response_status,
 completed_at,usage_link_version,usage_link_checked_version,usage_link_retry_until
 FROM token_analysis_request_summaries WHERE archive_id IN ('d5a496e050ad7291aa0c2f4f8f40eece','73eb6d29496d6c677054f5c797996d66')) x;
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);

BEGIN READ ONLY;
SET LOCAL statement_timeout='45s';
SET LOCAL lock_timeout='2s';
WITH s AS MATERIALIZED (SELECT * FROM token_analysis_request_summaries WHERE event_time >= TIMESTAMPTZ '2026-10-26T09:00:00+08:00' AND event_time < TIMESTAMPTZ '2026-10-27T09:00:00+08:00' AND usage_log_id IS NULL),
 j AS (SELECT s.*,u.id exact_bill_id FROM s LEFT JOIN LATERAL(
 SELECT id FROM usage_logs u WHERE u.api_key_id=s.api_key_id
 AND ((s.client_request_id<>'' AND u.request_id='client:'||s.client_request_id) OR (s.response_id<>'' AND u.request_id=s.response_id))
 AND u.created_at>=TIMESTAMPTZ '2026-10-26T09:00:00+08:00'-INTERVAL '2 hours' AND u.created_at<TIMESTAMPTZ '2026-10-27T09:00:00+08:00'+INTERVAL '2 hours'
 LIMIT 1) u ON true)
 SELECT jsonb_build_object('unlinked',count(*),'pending',count(*) FILTER(WHERE usage_link_version<>usage_link_checked_version),
 'failed',count(*) FILTER(WHERE response_status<200 OR response_status>=300),
 'missing_response',count(*) FILTER(WHERE completed_at IS NULL),
 'count_tokens',count(*) FILTER(WHERE endpoint LIKE '%/count_tokens'),
 'compact',count(*) FILTER(WHERE endpoint LIKE '%/compact'),
 'exact_bill_exists',count(exact_bill_id),
 'exact_bill_exists_pending',count(*) FILTER(WHERE exact_bill_id IS NOT NULL AND usage_link_version<>usage_link_checked_version),
 'exact_bill_exists_nonpending',count(*) FILTER(WHERE exact_bill_id IS NOT NULL AND usage_link_version=usage_link_checked_version),
 'pending_expired',count(*) FILTER(WHERE usage_link_version<>usage_link_checked_version AND usage_link_retry_until<now())) FROM j;
ROLLBACK;
SELECT jsonb_build_object('read_only',current_setting('transaction_read_only'),'rollback_completed',true);

